const input = $input.first().json;
const topic = input.topic;
const config = input.config;
const endpoints = input.endpoints;
const st = $getWorkflowStaticData('global');
if (!st.cache) st.cache = {};
const ttl = (config.cache_ttl_minutes || 30) * 60 * 1000;
const now = Date.now();

if (st.cache[topic] && (now - st.cache[topic].ts < ttl)) {
  return [{
    json: {
      cache_hit: true,
      topic,
      config,
      endpoints,
      cached_items: st.cache[topic].items || [],
      cached_hits: st.cache[topic].items.length
    }
  }];
}

return [{
  json: {
    cache_hit: false,
    topic,
    config,
    endpoints,
    cached_items: [],
    cached_hits: 0
  }
}];

const data = $json;
if (!data.cached_items || data.cached_items.length === 0) {
  return [{ json: { __empty: true, __stream: 'cache', __meta: { cached_hits: 0, api_calls: 0, failed_calls: 0 } } }];
}
return data.cached_items.map(i => ({
  json: { ...i, meta: { ...i.meta, cached: true }, __meta: { cached_hits: data.cached_items.length, api_calls: 0, failed_calls: 0 } }
}));

const gate = $('Cache Gate').first().json;
const topic = gate.topic;
const data = $json;

if (!data || !data.items || data.error) {
  return [{ json: { __empty: true, __src: 'stackoverflow', __meta: { failed_calls: 1 } } }];
}

return data.items.map(i => ({
  json: {
    source: "stackoverflow",
    topic,
    title: i.title,
    url: i.link,
    published_at: new Date(i.creation_date * 1000).toISOString(),
    raw_score: i.score || 0,
    score: (i.score || 0) + (i.answer_count || 0),
    summary_raw: i.body_markdown ? i.body_markdown.substring(0, 200) : null,
    summary: null,
    meta: { author: i.owner?.display_name, venue: "Stack Overflow", cached: false }
  }
}));

const gate = $('Cache Gate').first().json;
const topic = gate.topic;
const data = $json;

if (!data || !data.items || data.error) {
  return [{ json: { __empty: true, __src: 'github', __meta: { failed_calls: 1 } } }];
}

return data.items.map(i => ({
  json: {
    source: "github",
    topic,
    title: i.name,
    url: i.html_url,
    published_at: i.updated_at,
    raw_score: 0,
    score: (i.stargazers_count || 0) + (i.forks_count || 0),
    summary_raw: i.description,
    summary: null,
    meta: { author: i.owner?.login, venue: "GitHub", cached: false }
  }
}));

const gate = $('Cache Gate').first().json;
const topic = gate.topic;
const xmlStr = $json;

if (!xmlStr || xmlStr.error) {
  return [{ json: { __empty: true, __src: 'arxiv', __meta: { failed_calls: 1 } } }];
}

const entries = xmlStr.match(/<entry>[\s\S]*?<\/entry>/g) || [];
if (entries.length === 0) {
  return [{ json: { __empty: true, __src: 'arxiv', __meta: { failed_calls: 0 } } }];
}

return entries.map(e => {
  const title = (e.match(/<title>([\s\S]*?)<\/title>/) || [])[1] || "";
  const id = (e.match(/<id>([\s\S]*?)<\/id>/) || [])[1] || "";
  const summary = (e.match(/<summary>([\s\S]*?)<\/summary>/) || [])[1] || "";
  const published = (e.match(/<published>([\s\S]*?)<\/published>/) || [])[1] || null;
  return {
    json: {
      source: "arxiv",
      topic,
      title: title.replace(/\n/g, ' ').trim(),
      url: id,
      published_at: published,
      raw_score: 0,
      score: 10,
      summary_raw: summary.replace(/<[^>]+>/g, '').trim(),
      summary: null,
      meta: { author: null, venue: "arXiv", cached: false }
    }
  };
});

const gate = $('Cache Gate').first().json;
const topic = gate.topic;
const st = $getWorkflowStaticData('global');
if (!st.cache) st.cache = {};

const allItems = $input.all();
let failedCalls = 0;
const validItems = allItems
  .map(i => i.json)
  .filter(i => {
    if (i.__empty) {
      if (i.__meta?.failed_calls) failedCalls += i.__meta.failed_calls;
      else failedCalls++;
      return false;
    }
    return true;
  });

st.cache[topic] = { ts: Date.now(), items: validItems };

if (validItems.length === 0) {
  return [{ json: { __empty: true, topic, __meta: { cached_hits: 0, api_calls: 3, failed_calls: failedCalls || 3 } } }];
}

return validItems.map(i => ({
  json: { ...i, __meta: { cached_hits: 0, api_calls: 3, failed_calls: 0 } }
}));
